14	{
15	    case Run = 'Run';
16	    case TrailRun = 'TrailRun';
17	    case VirtualRun = 'VirtualRun';
18	    case Walk = 'Walk';
19	    case Hike = 'Hike';
20	    case Ride = 'Ride';
21	    case EBikeRide = 'EBikeRide';
22	    case GravelRide = 'GravelRide';
23	    case MountainBikeRide = 'MountainBikeRide';
24	    case Workout = 'Workout';
25	    case Golf = 'Golf';
26	    case Yoga = 'Yoga';
27	    case Snowboard = 'Snowboard';
28	    case NordicSki = 'NordicSki';
29	
30	    public function getLabel(): string
31	    {
32	        return match ($this) {
33	            self::Run => 'Corsa',
34	            self::TrailRun => 'Trail running',
35	            self::VirtualRun => 'Corsa virtuale',
36	            self::Walk => 'Camminata',
37	            self::Hike => 'Trekking',
38	            self::Ride => 'Bici',
39	            self::EBikeRide => 'E-bike',
