3	namespace App\Filament\Widgets\Concerns;
4	
5	use App\Models\User;
6	use Carbon\Carbon;
7	use Filament\Widgets\Concerns\InteractsWithPageFilters;
8	use Illuminate\Contracts\Support\Htmlable;
9	use Illuminate\Database\Eloquent\Builder;
10	use Illuminate\Support\HtmlString;
11	
12	/**
13	 * Query base condivisa dai widget di classifica: utenti con almeno
14	 * un'attività nel mese/sport selezionato, con l'aggregato passato come
15	 * $selectExpression esposto come colonna $alias per l'ordinamento.
16	 */
17	trait BuildsLeaderboardQuery
18	{
19	    use InteractsWithPageFilters;
20	
21	    public function updatedFilters(): void
22	    {
23	        $this->resetPage();
24	    }
25	
26	    protected function getLeaderboardQuery(string $selectExpression, string $alias): Builder
27	    {
28	        $month = $this->filters['month'] ?? null;
29	        $sportTypes = $this->filters['sportTypes'] ?? [];
30	
31	        $monthStart = $month ? Carbon::createFromFormat('Y-m', $month) : Carbon::now();
32	
33	        return User::query()
34	            ->select('users.*')
35	            ->selectRaw("{$selectExpression} as {$alias}")
36	            ->join('activities', 'activities.user_id', '=', 'users.id')
37	            ->whereNull('activities.deleted_at')
38	            ->whereBetween('activities.start_date_local', [
39	                $monthStart->copy()->startOfMonth(),
40	                $monthStart->copy()->endOfMonth(),
41	            ])
42	            ->when(
43	                filled($sportTypes),
44	                fn (Builder $query) => $query->whereIn('activities.sport_type', $sportTypes)
45	            )
46	            ->groupBy('users.id')
47	            ->orderByDesc($alias);
48	    }
49	
50	    /**
51	     * Titolo del widget con immagine accanto al testo (asset in public/images/leaderboard/,
52	     * oggi placeholder in attesa delle immagini definitive).
53	     */
54	    protected function headingWithImage(string $imagePath, string $label): Htmlable
55	    {
56	        return new HtmlString(sprintf(
57	            '<div class="flex items-center gap-2"><img src="%s" alt="" class="h-8 w-8 rounded"><span>%s</span></div>',
58	            e(asset($imagePath)),
59	            e($label),
60	        ));
61	    }
62	}
