3	namespace App\Filament\Concerns;
4	
5	use App\Enums\SportType;
6	use App\Models\Activity;
7	use Carbon\Carbon;
8	use Filament\Forms\Components\CheckboxList;
9	use Filament\Forms\Components\Select;
10	use Filament\Forms\Form;
11	use Filament\Pages\Dashboard\Concerns\HasFiltersForm;
12	use Illuminate\Support\Collection;
13	
14	/**
15	 * Filtro per le Classifiche: un singolo mese (non un intervallo, la
16	 * classifica è sempre per un mese alla volta) più i tipi di sport da
17	 * includere, dato che sport_type non ha ancora una mappatura condivisa
18	 * nell'app (vedi App\Enums\SportType).
19	 */
20	trait HasLeaderboardFilter
21	{
22	    use HasFiltersForm {
23	        mountHasFilters as baseMountHasFilters;
24	    }
25	
26	    public function mountHasFilters(): void
27	    {
28	        $this->baseMountHasFilters();
29	
30	        if (filled($this->filters['month'] ?? null) && filled($this->filters['sportTypes'] ?? null)) {
31	            return;
32	        }
33	
34	        if (blank($this->filters['month'] ?? null)) {
35	            $this->filters['month'] = $this->getActivitiesMonthRange()->last();
36	        }
37	
38	        // CheckboxList inizializza il filtro a un array vuoto, non a null:
39	        // "??=" non lo sovrascriverebbe mai con i default.
40	        if (blank($this->filters['sportTypes'] ?? null)) {
41	            $this->filters['sportTypes'] = SportType::leaderboardDefaults();
42	        }
43	
44	        $this->getFiltersForm()->fill($this->filters);
45	
46	        if ($this->persistsFiltersInSession()) {
47	            session()->put($this->getFiltersSessionKey(), $this->filters);
48	        }
49	    }
50	
51	    /**
52	     * Passa i filtri ai widget di classifica ospitati in pagina, che li
53	     * leggono tramite Widgets\Concerns\InteractsWithPageFilters.
54	     *
55	     * @return array<string, mixed>
56	     */
57	    public function getWidgetData(): array
58	    {
59	        return [
60	            'filters' => $this->filters,
61	        ];
62	    }
63	
64	    public function filtersForm(Form $form): Form
65	    {
66	        return $form
67	            ->schema([
68	                Select::make('month')
69	                    ->label('Mese')
70	                    ->options(fn () => $this->getMonthOptions())
71	                    ->native(false)
72	                    ->searchable()
73	                    ->optionsLimit($this->getActivitiesMonthRange()->count())
74	                    ->required()
75	                    ->live(),
76	                // per ora commentato, facciamo affidamento su SportType::leaderboardDefaults (v. sopra)
77	                /* CheckboxList::make('sportTypes')
78	                    ->label('Tipi di attività')
79	                    ->options(SportType::class)
80	                    ->columns(3)
81	                    ->live(), */
82	            ])
83	            ->columns(1);
84	    }
85	
86	    /**
87	     * @return array<string, string>
88	     */
89	    protected function getMonthOptions(): array
90	    {
91	        return $this->getActivitiesMonthRange()
92	            ->mapWithKeys(fn (string $month) => [
93	                $month => ucfirst(Carbon::createFromFormat('Y-m', $month)->locale('it')->translatedFormat('F Y')),
94	            ])
95	            ->all();
96	    }
97	
98	    /**
99	     * Mesi (formato 'Y-m') fra la prima e l'ultima attività registrata,
100	     * su tutti gli utenti (la classifica è cross-utente).
101	     *
102	     * @return Collection<int, string>
103	     */
104	    protected function getActivitiesMonthRange(): Collection
105	    {
106	        return once(function () {
107	            $bounds = Activity::query()
108	                ->selectRaw('min(start_date_local) as min, max(start_date_local) as max')
109	                ->first();
110	
111	            $start = $bounds?->min ? Carbon::parse($bounds->min) : Carbon::now();
112	            $end = $bounds?->max ? Carbon::parse($bounds->max) : Carbon::now();
113	
114	            $months = collect();
115	            $cursor = $start->copy()->startOfMonth();
116	
117	            while ($cursor->lte($end)) {
118	                $months->push($cursor->format('Y-m'));
119	                $cursor->addMonth();
120	            }
121	
122	            return $months;
123	        });
124	    }
125	}
