3	namespace App\Filament\Widgets;
4	
5	use App\Enums\ActivityType;
6	use App\Filament\Widgets\Concerns\GroupsActivitiesByType;
7	use Carbon\Carbon;
8	use Filament\Support\Colors\Color;
9	use Filament\Support\RawJs;
10	use Filament\Widgets\ChartWidget;
11	use Illuminate\Support\Collection;
12	
13	/**
14	 * Andamento mensile dei km percorsi, una linea per tipo di attività,
15	 * filtrato per il periodo selezionato in pagina.
16	 */
17	class DistanceTrendChartWidget extends ChartWidget
18	{
19	    use GroupsActivitiesByType;
20	
21	    protected static ?string $heading = null;
22	
23	    protected static ?string $maxHeight = '420px';
24	
25	    protected int|string|array $columnSpan = 'full';
26	
27	    protected function getType(): string
28	    {
29	        return 'line';
30	    }
31	
32	    protected function getData(): array
33	    {
34	        $rows = $this->getTypeMonthlyTotals('COALESCE(SUM(distance), 0)');
35	
36	        if ($rows->isEmpty()) {
37	            return [
38	                'datasets' => [['data' => []]],
39	                'labels' => [],
40	            ];
41	        }
42	
43	        $months = $this->getMonthRange($rows);
44	
45	        $datasets = $rows->groupBy('type')
46	            ->map(function (Collection $typeRows, string $type) use ($months) {
47	                $activityType = ActivityType::tryFrom($type);
48	                $totalsByMonth = $typeRows->pluck('total', 'month');
49	                $color = $this->colorToRgb($activityType?->getColor() ?? Color::Gray);
50	
51	                return [
52	                    'label' => $activityType?->getLabel() ?? 'Sconosciuto',
53	                    'data' => $months
54	                        ->map(fn (string $month): float => round(((float) ($totalsByMonth[$month] ?? 0)) / 1000, 1))
55	                        ->all(),
56	                    'borderColor' => $color,
57	                    'backgroundColor' => $color,
58	                    'fill' => false,
59	                    'tension' => 0.3,
60	                ];
61	            })
62	            ->values();
63	
64	        return [
65	            'datasets' => $datasets->all(),
66	            'labels' => $months
67	                ->map(fn (string $month): string => ucfirst(
68	                    Carbon::createFromFormat('Y-m', $month)->locale('it')->translatedFormat('M Y')
69	                ))
70	                ->all(),
71	        ];
72	    }
73	
74	    protected function getOptions(): RawJs
75	    {
76	        return RawJs::make(<<<'JS'
77	            {
78	                scales: {
79	                    y: {
80	                        beginAtZero: true,
81	                    },
82	                },
83	                plugins: {
84	                    tooltip: {
85	                        callbacks: {
86	                            label: (context) => ` ${context.dataset.label}: ${context.parsed.y.toLocaleString('it-IT')} km`,
87	                        },
88	                    },
89	                },
90	            }
91	        JS);
92	    }
93	
94	    /**
95	     * Mesi consecutivi fra il primo e l'ultimo presenti nei dati, così le
96	     * linee restano continue anche nei mesi senza attività di un dato tipo.
97	     *
98	     * @param  Collection<int, object{month: string}>  $rows
99	     * @return Collection<int, string>
100	     */
101	    private function getMonthRange(Collection $rows): Collection
102	    {
103	        $sortedMonths = $rows->pluck('month')->unique()->sort()->values();
104	
105	        $cursor = Carbon::createFromFormat('Y-m', $sortedMonths->first())->startOfMonth();
106	        $end = Carbon::createFromFormat('Y-m', $sortedMonths->last())->startOfMonth();
107	
108	        $months = collect();
109	
110	        while ($cursor->lte($end)) {
111	            $months->push($cursor->format('Y-m'));
112	            $cursor->addMonth();
113	        }
114	
115	        return $months;
116	    }
117	}
