3	namespace App\Console\Commands;
4	
5	use Carbon\Carbon;
6	use App\Models\User;
7	use App\Domain\StatsCalculator;
8	use Illuminate\Console\Command;
9	use App\Domain\Activity\ActivityTypeEnum;
10	use Exception;
11	
12	class ActivitiesStats extends Command
13	{
14	    /**
15	     * The name and signature of the console command.
16	     *
17	     * @var string
18	     */
19	    protected $signature = 'activities:stats
20	        {--users= : comma separated ids of users}
21	        {--start= : start date (format Y-m-d)}
22	        {--end= : end date (format Y-m-d)}
23	        {--type= : activity type, must be a valid activity type enum key}
24	        {--gear= : id of gear}
25	    ';
26	
27	    /**
28	     * The console command description.
29	     *
30	     * @var string
31	     */
32	    protected $description = 'Executes stats on activities';
33	
34	    /**
35	     * Execute the console command.
36	     */
37	    public function handle()
38	    {
39	        $type = (string)strtoupper($this->option('type'));
40	
41	        $service = new StatsCalculator();
42	
43	        /**
44	         * Loop through options and call appropiate method on calculator
45	         */
46	        if($type) {
47	            $service->setActivityType(constant(ActivityTypeEnum::class . "::$type"));
48	        }
49	
50	        if($this->option('start')) {
51	            $service->setStartDate(Carbon::parse($this->option('start')));
52	        }
53	
54	        if($this->option('end')) {
55	            $service->setEndDate(Carbon::parse($this->option('end')));
56	        }
57	
58	        if($this->option('users')) {
59	            $ids = explode(',', $this->option('users'));
60	            $users = User::whereIn('id', $ids)->get();
61	            if(count($users) < count($ids)) {
62	                throw new Exception("Some users were not found");
63	            }
64	            $service->setUsers($users);
65	        }
66	
67	        if($this->option('gear')) {
68	            $service->setGearId((int)($this->option('gear')));
69	        }
70	
71	    }
72	}
