1	<?php
2	
3	namespace App\Enums;
4	
5	use App\Enums\SpeedUnit;
6	use Filament\Support\Colors\Color;
7	use Filament\Support\Contracts\HasColor;
8	use Filament\Support\Contracts\HasIcon;
9	use Filament\Support\Contracts\HasLabel;
10	
11	/**
12	 * Valori del campo `sport_type` di Strava: sostituisce il legacy `type`
13	 * (deprecato da Strava ma ancora popolato), di cui è un raffinamento — ogni
14	 * `type` si scompone in uno o più `sport_type` (es. `Ride` → `Ride`,
15	 * `GravelRide`, `MountainBikeRide`). Elenco chiuso, unione dei valori
16	 * osservati nei dati dell'app e dei valori del legacy `type`, da estendere
17	 * se in futuro compaiono nuovi sport_type da Strava.
18	 */
19	enum SportType: string implements HasColor, HasIcon, HasLabel
20	{
21	    case AlpineSki = 'AlpineSki';
22	    case BackcountrySki = 'BackcountrySki';
23	    case Canoeing = 'Canoeing';
24	    case Crossfit = 'Crossfit';
25	    case EBikeRide = 'EBikeRide';
26	    case Elliptical = 'Elliptical';
27	    case Golf = 'Golf';
28	    case GravelRide = 'GravelRide';
29	    case Handcycle = 'Handcycle';
30	    case Hike = 'Hike';
31	    case IceSkate = 'IceSkate';
32	    case InlineSkate = 'InlineSkate';
33	    case Kayaking = 'Kayaking';
34	    case Kitesurf = 'Kitesurf';
35	    case MountainBikeRide = 'MountainBikeRide';
36	    case NordicSki = 'NordicSki';
37	    case Ride = 'Ride';
38	    case RockClimbing = 'RockClimbing';
39	    case RollerSki = 'RollerSki';
40	    case Rowing = 'Rowing';
41	    case Run = 'Run';
42	    case Sail = 'Sail';
43	    case Skateboard = 'Skateboard';
44	    case Snowboard = 'Snowboard';
45	    case Snowshoe = 'Snowshoe';
46	    case Soccer = 'Soccer';
47	    case StairStepper = 'StairStepper';
48	    case StandUpPaddling = 'StandUpPaddling';
49	    case Surfing = 'Surfing';
50	    case Swim = 'Swim';
51	    case TrailRun = 'TrailRun';
52	    case Velomobile = 'Velomobile';
53	    case VirtualRide = 'VirtualRide';
54	    case VirtualRun = 'VirtualRun';
55	    case Walk = 'Walk';
56	    case WeightTraining = 'WeightTraining';
57	    case Wheelchair = 'Wheelchair';
58	    case Windsurf = 'Windsurf';
59	    case Workout = 'Workout';
60	    case Yoga = 'Yoga';
61	
62	    public function getLabel(): string
63	    {
64	        return match ($this) {
65	            self::AlpineSki => 'Sci alpino',
66	            self::BackcountrySki => 'Sci fuoripista',
67	            self::Canoeing => 'Canoa',
68	            self::Crossfit => 'Crossfit',
69	            self::EBikeRide => 'E-bike',
70	            self::Elliptical => 'Ellittica',
71	            self::Golf => 'Golf',
72	            self::GravelRide => 'Bici da gravel',
73	            self::Handcycle => 'Handbike',
74	            self::Hike => 'Trekking',
75	            self::IceSkate => 'Pattinaggio su ghiaccio',
76	            self::InlineSkate => 'Pattini in linea',
77	            self::Kayaking => 'Kayak',
78	            self::Kitesurf => 'Kitesurf',
79	            self::MountainBikeRide => 'Mountain bike',
80	            self::NordicSki => 'Sci di fondo',
81	            self::Ride => 'Bici',
82	            self::RockClimbing => 'Arrampicata',
83	            self::RollerSki => 'Sci a rotelle',
84	            self::Rowing => 'Canottaggio',
85	            self::Run => 'Corsa',
86	            self::Sail => 'Vela',
87	            self::Skateboard => 'Skateboard',
88	            self::Snowboard => 'Snowboard',
89	            self::Snowshoe => 'Ciaspole',
90	            self::Soccer => 'Calcio',
91	            self::StairStepper => 'Stepper',
92	            self::StandUpPaddling => 'SUP',
93	            self::Surfing => 'Surf',
94	            self::Swim => 'Nuoto',
95	            self::TrailRun => 'Trail running',
96	            self::Velomobile => 'Velomobile',
97	            self::VirtualRide => 'Bici virtuale',
98	            self::VirtualRun => 'Corsa virtuale',
99	            self::Walk => 'Camminata',
100	            self::WeightTraining => 'Pesi',
101	            self::Wheelchair => 'Carrozzina',
102	            self::Windsurf => 'Windsurf',
103	            self::Workout => 'Allenamento',
104	            self::Yoga => 'Yoga',
105	        };
106	    }
107	
108	    /**
109	     * Colore per famiglia di sport. I tipi osservati nei dati reali
110	     * dell'app hanno ciascuno una tinta unica; i tipi mai visti finora
111	     * sono raggruppati per famiglia sulle tinte restanti.
112	     *
113	     * @return array{50: string, 100: string, 200: string, 300: string, 400: string, 500: string, 600: string, 700: string, 800: string, 900: string, 950: string}
114	     */
115	    public function getColor(): array
116	    {
117	        return match ($this) {
118	            self::Run => Color::Orange,
119	            self::TrailRun => Color::Red,
120	            self::VirtualRun => Color::Amber,
121	            self::Ride => Color::Blue,
122	            self::GravelRide => Color::Teal,
123	            self::MountainBikeRide => Color::Emerald,
124	            self::Walk => Color::Green,
125	            self::Hike => Color::Yellow,
126	            self::EBikeRide => Color::Cyan,
127	            self::Snowboard => Color::Sky,
128	            self::NordicSki => Color::Indigo,
129	            self::Workout => Color::Violet,
130	            self::Golf => Color::Lime,
131	            self::Yoga => Color::Pink,
132	
133	            self::VirtualRide, self::Velomobile, self::Handcycle => Color::Purple,
134	
135	            self::Canoeing, self::Kayaking, self::Rowing, self::Sail,
136	            self::StandUpPaddling, self::Surfing, self::Swim,
137	            self::Kitesurf, self::Windsurf => Color::Fuchsia,
138	
139	            self::AlpineSki, self::BackcountrySki, self::RollerSki, self::IceSkate => Color::Slate,
140	
141	            self::Crossfit, self::Elliptical, self::StairStepper, self::WeightTraining => Color::Rose,
142	
143	            self::Soccer, self::Skateboard, self::InlineSkate,
144	            self::RockClimbing, self::Wheelchair => Color::Zinc,
145	
146	            self::Snowshoe => Color::Stone,
147	        };
148	    }
149	
150	    /**
151	     * Icone Tabler (pacchetto secondnetwork/blade-tabler-icons): Heroicons
152	     * non ha icone sportive dedicate, Tabler sì. Dove manca un'icona
153	     * specifica si usa quella dello sport più simile della stessa famiglia
154	     * (es. non esiste un'icona dedicata a trail running/gravel/MTB).
155	     */
