3	namespace App\Filament\Concerns;
4	
5	use App\Enums\SportType;
6	use App\Models\Activity;
7	use Carbon\Carbon;
8	use Filament\Forms\Components\CheckboxList;
9	use Filament\Forms\Components\Select;
10	use Filament\Forms\Form;
11	use Filament\Pages\Dashboard\Concerns\HasFiltersForm;
12	use Illuminate\Support\Collection;
13	
14	/**
15	 * Filtro per le Classifiche: un singolo mese (non un intervallo, la
16	 * classifica è sempre per un mese alla volta) più i tipi di sport da
17	 * includere (vedi App\Enums\SportType).
18	 */
19	trait HasLeaderboardFilter
20	{
21	    use HasFiltersForm {
22	        mountHasFilters as baseMountHasFilters;
23	    }
24	
25	    public function mountHasFilters(): void
26	    {
27	        $this->baseMountHasFilters();
28	
29	        if (filled($this->filters['month'] ?? null) && filled($this->filters['sportTypes'] ?? null)) {
30	            return;
31	        }
32	
33	        if (blank($this->filters['month'] ?? null)) {
34	            $this->filters['month'] = $this->getActivitiesMonthRange()->last();
35	        }
36	
37	        // CheckboxList inizializza il filtro a un array vuoto, non a null:
38	        // "??=" non lo sovrascriverebbe mai con i default.
39	        if (blank($this->filters['sportTypes'] ?? null)) {
40	            $this->filters['sportTypes'] = SportType::leaderboardDefaults();
41	        }
42	
43	        $this->getFiltersForm()->fill($this->filters);
44	
45	        if ($this->persistsFiltersInSession()) {
46	            session()->put($this->getFiltersSessionKey(), $this->filters);
47	        }
48	    }
49	
50	    /**
51	     * Passa i filtri ai widget di classifica ospitati in pagina, che li
52	     * leggono tramite Widgets\Concerns\InteractsWithPageFilters.
53	     *
54	     * @return array<string, mixed>
55	     */
56	    public function getWidgetData(): array
57	    {
58	        return [
59	            'filters' => $this->filters,
60	        ];
61	    }
62	
63	    public function filtersForm(Form $form): Form
64	    {
65	        return $form
66	            ->schema([
67	                Select::make('month')
68	                    ->label('Mese')
69	                    ->options(fn () => $this->getMonthOptions())
70	                    ->native(false)
71	                    ->searchable()
72	                    ->optionsLimit($this->getActivitiesMonthRange()->count())
73	                    ->required()
74	                    ->live(),
75	                // per ora commentato, facciamo affidamento su SportType::leaderboardDefaults (v. sopra)
76	                CheckboxList::make('sportTypes')
77	                    ->label('Tipi di attività')
78	                    ->options(SportType::class)
79	                    ->columns(3)
80	                    ->live(),
81	            ])
82	            ->columns(1);
83	    }
84	
85	    /**
86	     * @return array<string, string>
87	     */
88	    protected function getMonthOptions(): array
89	    {
90	        return $this->getActivitiesMonthRange()
91	            ->mapWithKeys(fn (string $month) => [
92	                $month => ucfirst(Carbon::createFromFormat('Y-m', $month)->locale('it')->translatedFormat('F Y')),
93	            ])
94	            ->all();
95	    }
96	
97	    /**
98	     * Mesi (formato 'Y-m') fra la prima e l'ultima attività registrata,
99	     * su tutti gli utenti (la classifica è cross-utente).
100	     *
101	     * @return Collection<int, string>
102	     */
103	    protected function getActivitiesMonthRange(): Collection
104	    {
105	        return once(function () {
106	            $bounds = Activity::query()
107	                ->selectRaw('min(start_date_local) as min, max(start_date_local) as max')
108	                ->first();
109	
110	            $start = $bounds?->min ? Carbon::parse($bounds->min) : Carbon::now();
111	            $end = $bounds?->max ? Carbon::parse($bounds->max) : Carbon::now();
112	
113	            $months = collect();
114	            $cursor = $start->copy()->startOfMonth();
115	
116	            while ($cursor->lte($end)) {
117	                $months->push($cursor->format('Y-m'));
118	                $cursor->addMonth();
119	            }
120	
121	            return $months;
122	        });
123	    }
124	}
