input.new_string:
    /**
     * Titolo del widget con immagine accanto al testo (asset in public/images/leaderboard/,
     * oggi placeholder in attesa delle immagini definitive). Il testo include
     * il nome della tab attiva (es. "Dislivello - Corsa").
     */
    protected function headingWithImage(string $imagePath, string $label): Htmlable
    {
        return new HtmlString(sprintf(
            '<div class="flex items-center gap-3"><img src="%s" alt="" class="rounded" style="height:3rem;width:3rem;object-fit:contain"><span>%s</span></div>',
            e(asset($imagePath)),
            e($this->appendActiveGroupLabel($label)),
        ));
    }

    private function appendActiveGroupLabel(string $label): string
    {
        $sportType = SportType::tryFrom(($this->filters['sportTypes'] ?? [])[0] ?? '');

        return $sportType ? "{$label} - {$sportType->getLabel()}" : $label;
    }
}

